mapper.update:
UPDATE APPROVAL_DOC
   SET STATUS = #{toStatus}
       , SUBMITTED_AT = #{at}, COMPLETED_AT = NULL
       , COMPLETED_AT = #{at}
       , SUBMITTED_AT = NULL, UPDATED_AT = #{at}
 WHERE DOC_ID = #{docId} AND STATUS = #{fromStatus} AND DELETED_YN = 'N'

mapper.sql:
WHERE D.DELETED_YN = 'N'


        AND D.STATUS = 'PROG'
        AND EXISTS (SELECT 1 FROM APPROVAL_LINE L WHERE L.DOC_ID = D.DOC_ID
                       AND L.APPROVER_ID = #{loginId} AND L.STATUS = 'PENDING')


        AND D.STATUS = 'PROG'
        AND (D.DRAFTER_ID = #{loginId}
             OR EXISTS (SELECT 1 FROM APPROVAL_LINE L WHERE L.DOC_ID = D.DOC_ID
                           AND L.APPROVER_ID = #{loginId} AND L.STATUS = 'APPROVED'))


        AND D.STATUS = 'DONE''REJECTED'
        AND (D.DRAFTER_ID = #{loginId}
             OR EXISTS (SELECT 1 FROM APPROVAL_LINE L WHERE L.DOC_ID = D.DOC_ID AND L.APPROVER_ID = #{loginId}))


        AND D.STATUS = 'DONE' AND D.RECEIVER_TYPE = 'external' AND D.RECEIVER = #{dept}


        AND D.STATUS = 'DRAFT' AND D.DRAFTER_ID = #{loginId}



    AND (D.TITLE LIKE '%' || #{q} || '%' OR D.DOC_NO LIKE '%' || #{q} || '%'
         OR D.DRAFTER_NAME LIKE '%' || #{q} || '%')

AND NVL(D.SUBMITTED_AT, D.CREATED_AT) >= #{from}

mapper.select:
SELECT * FROM (
    SELECT A.*, ROWNUM AS RN FROM (
        SELECT 
          FROM APPROVAL_DOC D

         ORDER BY NVL(D.COMPLETED_AT, NVL(D.SUBMITTED_AT, NVL(D.UPDATED_AT, D.CREATED_AT))) DESC, D.DOC_ID DESC
    ) A WHERE ROWNUM <= #{endRow}
) WHERE RN > #{startRow}
